python3 -c '
import subprocess, json

def run(cmd):
    return subprocess.check_output(cmd, shell=True).decode()

pods = json.loads(run("kubectl get pods -A -o json"))
for pod in pods["items"]:
    ns = pod["metadata"]["namespace"]
    name = pod["metadata"]["name"]
    # check container statuses
    statuses = pod.get("status", {}).get("containerStatuses", [])
    for st in statuses:
        if not st.get("ready") or st.get("restartCount", 0) > 0 or "waiting" in st.get("state", {}) or "terminated" in st.get("state", {}):
            print(f"=== POD: {ns}/{name} (container: {st.get(\"name\")}) ===")
            print(f"State: {st.get(\"state\")}")
            print(f"RestartCount: {st.get(\"restartCount\")}")
            # get container spec
            for c in pod["spec"]["containers"]:
                if c["name"] == st.get("name"):
                    print(f"Command: {c.get(\"command\")} Args: {c.get(\"args\")}")
            print()
'

