    const ns = pod.metadata.namespace;
    const name = pod.metadata.name;
    const statuses = pod.status?.containerStatuses || [];
    for (const st of statuses) {
        if (!st.ready || st.restartCount > 0 || st.state?.waiting || (st.state?.terminated && st.state?.terminated?.exitCode !== 0)) {
            console.log(`=== POD: ${ns}/${name} (container: ${st.name}) ===`);
            console.log(`State:`, JSON.stringify(st.state));
            console.log(`RestartCount: ${st.restartCount}`);
            for (const c of pod.spec.containers) {
                if (c.name === st.name) {
                    console.log(`Command:`, c.command, `Args:`, c.args);
                    console.log(`Env:`, c.env);
                }
            }
            console.log();
        }
    }
}
'

