node -e '
const cp = require("child_process");

const resources = ["deployments", "cronjobs", "statefulsets", "daemonsets", "configmaps", "services", "jobs"];
for (const res of resources) {
  const data = JSON.parse(cp.execSync(`kubectl get ${res} -A -o json`));
  for (const item of data.items) {
    const ns = item.metadata.namespace;
    const name = item.metadata.name;
    const lastApplied = item.metadata.annotations?.["kubectl.kubernetes.io/last-applied-configuration"];
    if (lastApplied) {
      try {
        const parsed = JSON.parse(lastApplied);
        // Compare spec or data
        if (item.data && parsed.data) {
          if (JSON.stringify(item.data) !== JSON.stringify(parsed.data)) {
            console.log(`[DIFF CM DATA] ${ns}/${name}:`);
            console.log("  Actual:", item.data);
            console.log("  Applied:", parsed.data);
          }
        }
        if (item.spec && parsed.spec) {
          // Compare replicas
          if (item.spec.replicas !== undefined && parsed.spec.replicas !== undefined && item.spec.replicas !== parsed.spec.replicas) {
            console.log(`[DIFF REPLICAS] ${ns}/${name}: actual=${item.spec.replicas}, applied=${parsed.spec.replicas}`);
          }
          // Compare container commands/images
          const actualContainers = item.spec.template?.spec?.containers || item.spec.jobTemplate?.spec?.template?.spec?.containers || [];
          const appliedContainers = parsed.spec.template?.spec?.containers || parsed.spec.jobTemplate?.spec?.template?.spec?.containers || [];
          for (let i = 0; i < actualContainers.length; i++) {
            const ac = actualContainers[i];
            const ap = appliedContainers[i];
            if (ap) {
              if (JSON.stringify(ac.command) !== JSON.stringify(ap.command)) {
                console.log(`[DIFF COMMAND] ${ns}/${name} container ${ac.name}: actual=${JSON.stringify(ac.command)}, applied=${JSON.stringify(ap.command)}`);
              }
              if (ac.image !== ap.image) {
                console.log(`[DIFF IMAGE] ${ns}/${name} container ${ac.name}: actual=${ac.image}, applied=${ap.image}`);
              }
            }
          }
        }
      } catch (e) {
        console.error(`Error parsing lastApplied for ${ns}/${name}:`, e);
      }
    }
  }
}
'

